#!/usr/bin/env python3
"""Regenerates the generated part of ebpf/insn.bend, in place.

  python3 gen/decode.py           rewrite the region between the lines
                                  "# BEGIN GENERATED by gen/decode.py: <name>"
                                  and "# END GENERATED: <name>"
  python3 gen/decode.py --check   only check that it is up to date

One region, "decode": the decoder's dispatch tables (RFC 9669, 3 to 5), one
def per instruction class (EbpfDec.ld, .ldx, .st, .stx, .alu, .jmp, .jmp32,
.alu64), each a chain over every opcode RFC 9669 defines in that class, and
EbpfDec.op, which picks the class from the opcode's low 3 bits. Each opcode's
candidate also checks that the fields the instruction does not use are zero
(strict decoding). Everything outside the region is written by hand.
"""
import os, sys

ALU_OPS = [  # name, code bits (the offset field selects SDIV/SMOD, MOVSX)
    ("EbpfAdd", 0), ("EbpfSub", 16), ("EbpfMul", 32), ("EbpfDiv", 48),
    ("EbpfOr", 64), ("EbpfAnd", 80), ("EbpfLsh", 96), ("EbpfRsh", 112),
    ("EbpfMod", 144), ("EbpfXor", 160), ("EbpfMov", 176), ("EbpfArsh", 192)]
CONDS = [("EbpfJeq", 16), ("EbpfJgt", 32), ("EbpfJge", 48), ("EbpfJset", 64), ("EbpfJne", 80),
         ("EbpfJsgt", 96), ("EbpfJsge", 112), ("EbpfJlt", 160), ("EbpfJle", 176),
         ("EbpfJslt", 192), ("EbpfJsle", 208)]
SIZES = [("EbpfSizeW", 0), ("EbpfSizeH", 8), ("EbpfSizeB", 16), ("EbpfSizeDW", 24)]
SMALL = [("EbpfSmallW", 0), ("EbpfSmallH", 8), ("EbpfSmallB", 16)]
ATOM = [("EbpfAtAdd", 0), ("EbpfAtOr", 64), ("EbpfAtAnd", 80), ("EbpfAtXor", 160)]

def z(f): return "U32.is_zero(%s)" % f
def r0(f): return "EbpfReg.is_r0(%s)" % f

def both(*cs):
    e = cs[-1]
    for c in reversed(cs[:-1]):
        e = "EbpfDec.both(%s, %s)" % (c, e)
    return e

def req(cs, d):
    return d if not cs else "EbpfDec.req(%s, %s)" % (both(*cs), d)

def chain(cands, var="code"):
    e = "EbpfDecBad{}"
    for c, d in reversed(cands):
        e = "EbpfDec.pick(U32.is_eq(%s, %d), %s, %s)" % (var, c, d, e)
    return e

def one(x): return "EbpfDecOne{%s}" % x

def alu_class(cls, wname):
    cands = []
    for n, b in ALU_OPS:
        for sbit, src in ((0, "K"), (8, "X")):
            code = cls | b | sbit
            if src == "K":
                checks = [r0("s")]
                mk = lambda op: one("EbpfAlu{EbpfBits%s{}, %s{}, d, EbpfK{imm}}" % (wname, op))
            else:
                checks = [z("imm")]
                mk = lambda op: one("EbpfAlu{EbpfBits%s{}, %s{}, d, EbpfX{s}}" % (wname, op))
            if n in ("EbpfDiv", "EbpfMod"):
                sn = "EbpfSdiv" if n == "EbpfDiv" else "EbpfSmod"
                d = "EbpfDec.pick(%s, %s, EbpfDec.req(U32.is_eq(off, 1), %s))" % (z("off"), mk(n), mk(sn))
                cands.append((code, req(checks, d)))
            elif n == "EbpfMov" and src == "X":
                if wname == "32":
                    sx = ("EbpfMovsx32{EbpfHalfB{}, d, s}", "EbpfMovsx32{EbpfHalfH{}, d, s}", None)
                else:
                    sx = ("EbpfMovsx64{EbpfSx8{}, d, s}", "EbpfMovsx64{EbpfSx16{}, d, s}", "EbpfMovsx64{EbpfSx32{}, d, s}")
                inner = "EbpfDecBad{}" if sx[2] is None else "EbpfDec.pick(U32.is_eq(off, 32), %s, EbpfDecBad{})" % one(sx[2])
                inner = "EbpfDec.pick(U32.is_eq(off, 16), %s, %s)" % (one(sx[1]), inner)
                inner = "EbpfDec.pick(U32.is_eq(off, 8), %s, %s)" % (one(sx[0]), inner)
                d = "EbpfDec.pick(%s, %s, %s)" % (z("off"), mk(n), inner)
                cands.append((code, req(checks, d)))
            else:
                cands.append((code, req(checks + [z("off")], mk(n))))
    cands.append((cls | 128, req([r0("s"), z("off"), z("imm")], one("EbpfNeg{EbpfBits%s{}, d}" % wname))))
    def endc(kind):
        e = "EbpfDecBad{}"
        for bits, v in (("EbpfE64", 64), ("EbpfE32", 32), ("EbpfE16", 16)):
            e = "EbpfDec.pick(U32.is_eq(imm, %d), %s, %s)" % (v, one("EbpfEnd{%s{}, %s{}, d}" % (kind, bits)), e)
        return e
    if wname == "32":
        cands.append((212, req([r0("s"), z("off")], endc("EbpfToLe"))))
        cands.append((220, req([r0("s"), z("off")], endc("EbpfToBe"))))
    else:
        cands.append((215, req([r0("s"), z("off")], endc("EbpfBswap"))))
    return chain(cands)

def jmp_class(cls, wname):
    cands = []
    for n, b in CONDS:
        cands.append((cls | b, req([r0("s")], one("EbpfJmp{EbpfBits%s{}, %s{}, d, EbpfK{imm}, off}" % (wname, n)))))
        cands.append((cls | b | 8, req([z("imm")], one("EbpfJmp{EbpfBits%s{}, %s{}, d, EbpfX{s}, off}" % (wname, n)))))
    if wname == "64":
        cands.append((5, req([r0("d"), r0("s"), z("imm")], one("EbpfJa{off}"))))
        cands.append((133, req([r0("d"), z("off")], "EbpfDec.call(EbpfCallKind.of_reg(s), imm)")))
        cands.append((149, req([r0("d"), r0("s"), z("off"), z("imm")], one("EbpfExit{}"))))
    else:
        cands.append((6, req([r0("d"), r0("s"), z("off")], one("EbpfJa32{imm}"))))
    return chain(cands)

def ld_class():
    cands = [(24, req([z("off")], "EbpfDec.lddw(EbpfLddwKind.of_reg(s), d, imm)"))]
    for n, b in SMALL:
        cands.append((32 | b, req([r0("d"), r0("s"), z("off")], one("EbpfLdAbs{%s{}, imm}" % n))))
        cands.append((64 | b, req([r0("d"), z("off")], one("EbpfLdInd{%s{}, s, imm}" % n))))
    return chain(cands)

def ldx_class():
    cands = [(97 | b, req([z("imm")], one("EbpfLdx{%s{}, d, s, off}" % n))) for n, b in SIZES]
    cands += [(129 | b, req([z("imm")], one("EbpfLdxs{%s{}, d, s, off}" % n))) for n, b in SMALL]
    return chain(cands)

def st_class():
    return chain([(98 | b, req([r0("s")], one("EbpfSt{%s{}, d, off, imm}" % n))) for n, b in SIZES])

def stx_class():
    cands = [(99 | b, req([z("imm")], one("EbpfStx{%s{}, d, s, off}" % n))) for n, b in SIZES]
    for sz, code in (("EbpfAtomicW", 195), ("EbpfAtomicDW", 219)):
        ac = []
        for an, ab in ATOM:
            ac.append((ab, one("EbpfAtomic{%s{}, %s{False{}}, d, s, off}" % (sz, an))))
            ac.append((ab | 1, one("EbpfAtomic{%s{}, %s{True{}}, d, s, off}" % (sz, an))))
        ac.append((225, one("EbpfAtomic{%s{}, EbpfAtXchg{}, d, s, off}" % sz)))
        ac.append((241, one("EbpfAtomic{%s{}, EbpfAtCmpxchg{}, d, s, off}" % sz)))
        cands.append((code, chain(ac, "imm")))
    return chain(cands)

def decode_region():
    classes = [("ld", ld_class()), ("ldx", ldx_class()), ("st", st_class()), ("stx", stx_class()),
               ("alu", alu_class(4, "32")), ("jmp", jmp_class(5, "64")), ("jmp32", jmp_class(6, "32")),
               ("alu64", alu_class(7, "64"))]
    out = []
    for name, body in classes:
        out.append("def EbpfDec.%s(+code: U32, +d: EbpfReg, +s: EbpfReg, +off: U32, +imm: U32) -> EbpfDec:\n  %s\n\n" % (name, body))
    e = "EbpfDecBad{}"
    for k, (name, _) in reversed(list(enumerate(classes))):
        e = "EbpfDec.pick(U32.is_eq(U32.and(code, 7), %d), EbpfDec.%s(code, d, s, off, imm), %s)" % (k, name, e)
    out.append("# what one slot's opcode and fields decode to, its registers decoded\n")
    out.append("def EbpfDec.op(+code: U32, +d: EbpfReg, +s: EbpfReg, +off: U32, +imm: U32) -> EbpfDec:\n  %s\n\n" % e)
    return "".join(out)

REGIONS = {"decode": decode_region()}

def main():
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "insn.bend")
    with open(path, encoding="utf-8", newline="") as f:
        src = f.read()
    new = src
    for name, body in REGIONS.items():
        begin = "# BEGIN GENERATED by gen/decode.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i = new.index(begin) + len(begin)
        j = new.index(end, i)
        new = new[:i] + body + new[j:]
    if "--check" in sys.argv[1:]:
        if new != src:
            print("insn.bend differs from what gen/decode.py generates")
            sys.exit(1)
        print("insn.bend is up to date")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)

main()
